1	//! Live integration tests against the real Amazon Bedrock Converse API.
2	//!
3	//! All tests are `#[ignore]` so they don't run in CI.
4	//! Activate locally with:
5	//! ```sh
6	//! BEDROCK_MODEL_ID=global.anthropic.claude-sonnet-5-5 \
7	//! AWS_DEFAULT_REGION=us-east-1 \
8	//! cargo test -p paigasus-helikon-providers-bedrock -- --ignored
9	//! ```
10	//!
11	//! ## Required environment variables
12	//!
13	//! | Variable | Description |
14	//! |---|---|
15	//! | `BEDROCK_MODEL_ID` | Bedrock model id to test against |
16	//! | `AWS_DEFAULT_REGION` | (or `AWS_REGION`) — AWS region |
17	//! | AWS credentials | Any standard AWS credential chain value |
18	//!
19	//! When any required variable is unset the test prints a loud skip message and
20	//! returns early (the test passes so CI stays green).
21	
22	use futures_util::StreamExt;
23	use paigasus_helikon_core::{
24	    CancellationToken, ContentPart, Item, Model, ModelEvent, ModelRequest, ResponseFormat, ToolDef,
25	};
26	use paigasus_helikon_providers_bedrock::BedrockModel;
27	
28	// ── helpers ───────────────────────────────────────────────────────────────────
29	
30	fn skip_if_missing_env() -> Option<String> {
31	    let model_id = match std::env::var("BEDROCK_MODEL_ID") {
32	        Ok(v) if !v.is_empty() => v,
33	        _ => {
34	            eprintln!(
35	                "[live] BEDROCK_MODEL_ID not set — skipping live Bedrock test. \
36	                 Set BEDROCK_MODEL_ID, AWS_DEFAULT_REGION, and AWS credentials to run."
37	            );
38	            return None;
39	        }
40	    };
41	    Some(model_id)
42	}
43	
44	fn user(s: &str) -> Item {
45	    Item::UserMessage {
46	        content: vec![ContentPart::Text { text: s.to_owned() }],
47	    }
48	}
49	
50	fn assistant(s: &str) -> Item {
51	    Item::AssistantMessage {
52	        content: vec![ContentPart::Text { text: s.to_owned() }],
53	        agent: None,
54	    }
55	}
56	
57	fn tool_call(call_id: &str, name: &str) -> Item {
58	    Item::ToolCall {
59	        call_id: call_id.to_owned(),
60	        name: name.to_owned(),
61	        args: serde_json::json!({}),
62	    }
63	}
64	
65	fn tool_result(call_id: &str, text: &str) -> Item {
66	    Item::ToolResult {
67	        call_id: call_id.to_owned(),
68	        content: vec![ContentPart::Text {
69	            text: text.to_owned(),
70	        }],
71	    }
72	}
73	
74	fn ping_tool() -> ToolDef {
75	    ToolDef {
76	        name: "ping".to_owned(),
77	        description: "Ping a host".to_owned(),
78	        schema: serde_json::json!({"type": "object", "properties": {}}),
79	    }
80	}
81	
82	/// Send `messages` (with optional `tools`) and assert the stream ends with no
83	/// `Err` event and carries at least one `TokenDelta` or `Finish` event.
84	async fn send_and_assert_ok(model_id: &str, messages: Vec<Item>, tools: Vec<ToolDef>) {
85	    let model = BedrockModel::from_env(model_id)
86	        .await
87	        .expect("from_env should succeed");
88	
89	    let mut req = ModelRequest::new();
90	    req.messages = messages;
91	    req.tools = tools;
92	    req.model_settings.max_output_tokens = Some(64);
93	
94	    let mut s = model
95	        .invoke(req, CancellationToken::new())
96	        .await
97	        .expect("invoke should succeed");
98	
99	    let mut had_error = false;
100	    let mut saw_output = false;
101	    while let Some(ev) = s.next().await {
102	        match ev {
103	            Ok(ModelEvent::TokenDelta { .. } | ModelEvent::Finish { .. }) => saw_output = true,
104	            Ok(_) => {}
105	            Err(e) => {
106	                eprintln!("[live] stream error: {e:?}");
107	                had_error = true;
108	            }
109	        }
110	    }
111	    assert!(!had_error, "stream must complete without error");
112	    assert!(saw_output, "stream must carry a TokenDelta or Finish event");
113	}
114	
115	// ── tests ─────────────────────────────────────────────────────────────────────
116	
117	/// Smoke test: send a one-turn text request and check the stream completes.
118	#[tokio::test]
119	#[ignore]
120	async fn smoke_text_turn() {
121	    let Some(model_id) = skip_if_missing_env() else {
122	        return;
123	    };
124	    let model = BedrockModel::from_env(&model_id)
125	        .await
126	        .expect("from_env should succeed");
127	
128	    let mut req = ModelRequest::new();
129	    req.messages = vec![user("Reply with exactly: hello")];
130	    req.model_settings.max_output_tokens = Some(64);
131	
132	    let mut s = model
133	        .invoke(req, CancellationToken::new())
134	        .await
135	        .expect("invoke should succeed");
136	
137	    let mut text = String::new();
138	    while let Some(ev) = s.next().await {
139	        match ev {
140	            Ok(ModelEvent::TokenDelta { text: t }) => text.push_str(&t),
141	            Ok(_) => {}
142	            Err(e) => panic!("stream error: {e:?}"),
143	        }
144	    }
145	    assert!(
146	        text.to_lowercase().contains("hello"),
147	        "expected 'hello' in response, got: {text:?}"
148	    );
149	}
150	
151	/// Exercises the JSON schema rewriter end-to-end with a tagged enum + nested
152	/// generic schema.  This validates the §4.2 acceptance criterion.
153	#[tokio::test]
154	#[ignore]
155	async fn tool_with_tagged_enum_and_nested_generic() {
156	    let Some(model_id) = skip_if_missing_env() else {
157	        return;
158	    };
159	
160	    // Only run this test against Anthropic/Nova models that support tools.
161	    let family = paigasus_helikon_providers_bedrock::ModelFamily::from_model_id(&model_id);
162	    let supports_tools = matches!(
163	        family,
164	        paigasus_helikon_providers_bedrock::ModelFamily::Anthropic
165	            | paigasus_helikon_providers_bedrock::ModelFamily::AmazonNova
166	    );
167	    if !supports_tools {
168	        eprintln!("[live] {model_id} does not support tools — skipping tool test");
169	        return;
170	    }
171	
172	    let model = BedrockModel::from_env(&model_id)
173	        .await
174	        .expect("from_env should succeed");
175	
176	    // Schema with a tagged enum (`type` field) and a nested generic container
177	    // (`data: { type: array, items: { type: string } }`).
