50	/// avoids `ValidationException` on models whose limit is below any hardcoded
51	/// value.
52	///
53	/// Returns `None` when all three fields (temperature, top_p, max_tokens) are
54	/// absent — Bedrock accepts a missing `inferenceConfig` and all its fields are
55	/// individually optional.
56	fn build_inference_config(req: &ModelRequest, cfg: &Config) -> Option<InferenceConfiguration> {
57	    let max_tokens = req
58	        .model_settings
59	        .max_output_tokens
60	        .or(cfg.max_output_default);
61	
62	    // When no inference field is set, omit the config block entirely.
63	    if req.model_settings.temperature.is_none()
64	        && req.model_settings.top_p.is_none()
65	        && max_tokens.is_none()
66	    {
67	        return None;
68	    }
69	
70	    let mut b = InferenceConfiguration::builder();
71	    if let Some(t) = req.model_settings.temperature {
72	        b = b.temperature(t);
73	    }
74	    if let Some(p) = req.model_settings.top_p {
75	        b = b.top_p(p);
76	    }
77	    if let Some(mt) = max_tokens {
78	        b = b.max_tokens(mt as i32);
79	    }
