152	    /// Resolve all settings and construct the [`crate::BedrockModel`].
153	    ///
154	    /// This is **synchronous** — no network calls are made.
155	    ///
156	    /// # Errors
157	    ///
158	    /// - [`BuildError::EmptyModelId`] — model id is an empty string.
159	    /// - [`BuildError::MissingClient`] — neither `.client(…)` nor
160	    ///   `.sdk_config(…)` was called (use [`crate::BedrockModel::from_env`] for
161	    ///   automatic env-based client construction).
162	    pub fn build(self) -> Result<crate::BedrockModel, BuildError> {
163	        // 1. Validate model id.
164	        if self.model_id.is_empty() {
165	            return Err(BuildError::EmptyModelId);
166	        }
167	
168	        // 2. Resolve client.
169	        let client = if let Some(c) = self.client {
170	            // Injected client wins; region override is ignored.
171	            if self.region.is_some() {
172	                tracing::debug!(
173	                    target: "paigasus::bedrock::builder",
174	                    "region() was set but a Client was injected — region override ignored; \
175	                     the injected client's region takes precedence",
176	                );
177	            }
178	            c
179	        } else if let Some(ref sdk_cfg) = self.sdk_config {
180	            if let Some(region) = self.region {
181	                // Region override: build a per-client config that layers the
182	                // override on top of the caller's SdkConfig, then construct
183	                // the client from that config.
184	                let client_cfg = aws_sdk_bedrockruntime::config::Builder::from(sdk_cfg)
185	                    .region(region)
186	                    .build();
187	                aws_sdk_bedrockruntime::Client::from_conf(client_cfg)
188	            } else {
189	                Client::new(sdk_cfg)
190	            }
191	        } else {
192	            return Err(BuildError::MissingClient);
193	        };
194	
195	        // 3. Detect family and resolve capabilities.
196	        let family = ModelFamily::from_model_id(&self.model_id);
197	        let default_caps = caps_for(family);
198	        let capabilities = self.capabilities_override.unwrap_or(default_caps);
199	        let max_output_default = self.max_output_override;
200	
201	        Ok(crate::BedrockModel(Arc::new(Config {
202	            client,
203	            model_id: self.model_id,
204	            family,
205	            capabilities,
206	            max_output_default,
207	        })))
208	    }
209	}
